import{z as o,x as n,o as B,c as p,q as r,j as i,D as e,d as l,s,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"VSB 对多束","description":"","frontmatter":{"title":"VSB 对多束","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/vsb-vs-multibeam.md","filePath":"litho/vsb-vs-multibeam.md","lastUpdated":1791063341000}'),d={name:"litho/vsb-vs-multibeam.md"};function S(m,a,V,C,u,D){const t=n("Mermaid");return B(),p("div",null,[a[2]||(a[2]=r('<h1 id="vsb-对多束" tabindex="-1">VSB 对多束 <a class="header-anchor" href="#vsb-对多束" aria-label="Permalink to &quot;VSB 对多束&quot;">​</a></h1><div class="epigraph"><p>变量成形束按矩形炮计数；多束按面积与剂量计数。选哪一种写入器，就是选哪一堵墙先撞上。</p><footer>—— 对照 NuFlare 一类 VSB 与 IMS 一类多束掩模写入的公开原理</footer></div><p><a href="/litho/multibeam-mask-writer">上一课</a>已经把多束收成：十万至数十万根并行细束，写入时间对图形复杂度一阶解耦，曲线 ILT 才进得了日历。缺口是对照。产线仍大量使用可变成形束（VSB）：用可变矩形孔径一次打一块曼哈顿。两种物理、两堵墙、两套 PEC，掩模厂混线而不是一夜切换。本课钉 VSB 对多束。全芯片计算如何赶上写入，留给 <a href="/litho/computational-litho-gpu">GPU OPC</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VSB 的节拍是：偏转 → 成形（矩形或三角形） → 曝光 → 稳定。炮数随 OPC 碎片和微矩形逼近曲线而涨，时间墙是炮数。公开的 NuFlare EBM 一类机台把单束电流、成形精度和 PEC 做到掩模厂熟悉的 CD 均匀；它们没有把「任意 ILT」的炮数变免费。</p><p><span class="marginnote">「可变成形束（VSB）」就是用一块可调大小的方形孔径，把电子束「裁」成任意矩形，像用各种尺寸的图章一枚一枚盖出图形；多束则是十几万枚小图章排成阵列同时盖——盖章方式不同，堵的墙也不同。</span></p><p>多束的节拍是：栅格扫描一场的时间 ≈ 面积 × 剂量 / 总电流。复杂度墙被拆掉，剩下面积墙、数据带宽和阵列校准。IMS 一类 MultiBeam Mask Writer 的公开原理就是这道交换。缺口是：哪一层该走哪座墙，而不是宣布 VSB 过时。</p><h3 id="简单层上-vsb-可以更快" tabindex="-1">简单层上 VSB 可以更快 <a class="header-anchor" href="#简单层上-vsb-可以更快" aria-label="Permalink to &quot;简单层上 VSB 可以更快&quot;">​</a></h3><p>稀疏接触、大面积铬、低 OPC 复杂度，VSB 单炮面积大，可能比多束扫完整场更短。多束的价值在复杂度尾部：碎 SRAF、全芯片曲线、短碎片曼哈顿。用「所有掩模都该多束」规划产能，会在简单层上买错机时，在 ILT 层上又排队。</p><p><span class="marginnote">不要把束数宣传常数（某代「二十六万束」）写进教材当永久物理。论证应落在「时间对复杂度的导数」，具体束数每代都会变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>混线：关键 EUV / ILT 层走多束，较松的 DUV 层留 VSB。数据准备必须双输出——VSB 炮表与多束位图——并共用一套套刻与 CD 基准，使不同写入器写的层仍能对上。PEC、充电、加热模型按机台家族分开校准：多束瞬时剂量率分布与 VSB 不同，VSB 经验表不能直接贴。</p><p>曲线在 VSB 上的权宜之计是微矩形逼近，炮数爆炸，正好说明为什么曲线 MRC 与多束要绑在一起。曼哈顿在多束上完全能写，只是可能浪费其复杂度不敏感的优势。</p><p><span class="marginnote">给炮数一个量级感：一段曲线斜坡若用半微米级微矩形去逼近，轻轻松松多出上万炮；VSB 的时间按炮数线性涨，多束的位图根本不数炮——这就是曲线层在 VSB 队列里排队的算术。</span></p><h3 id="误差指纹不同" tabindex="-1">误差指纹不同 <a class="header-anchor" href="#误差指纹不同" aria-label="Permalink to &quot;误差指纹不同&quot;">​</a></h3><p>VSB：成形孔径与偏转校准的残差，常表现为边的局部 CD 与位置误差，相对「几何」还比较像 OPC 熟悉的偏置。多束：阵列各通道电流/位置不均，留下栅格周期指纹，光学 OPC 很难当随机掩模误差来修。混线的计量必须能分辨这两种指纹，否则会把写入器问题送去「再跑 OPC」。</p>',16)),(B(),i(A,null,{default:e(()=>[s(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E6%8E%A9%E6%A8%A1%E4%B8%8A%E7%9C%8B%E5%88%B0%20CD%20%E6%88%96%E4%BD%8D%E7%BD%AE%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20Q%5B%22%E8%AF%AF%E5%B7%AE%E5%B8%A6%E5%93%AA%E7%A7%8D%E6%8C%87%E7%BA%B9%22%5D%0A%20%20Q%20--%3E%20E1%5B%22%E5%B1%80%E9%83%A8%E8%BE%B9%E5%81%8F%E7%BD%AE%EF%BC%8C%E9%9A%8F%E6%88%90%E5%BD%A2%E4%B8%8E%E5%81%8F%E8%BD%AC%E8%B5%B0%22%5D%0A%20%20Q%20--%3E%20E2%5B%22%E5%91%A8%E6%9C%9F%E6%A0%85%E6%A0%BC%E7%8A%B6%EF%BC%8C%E8%B7%A8%E5%9C%BA%E9%87%8D%E5%A4%8D%22%5D%0A%20%20E1%20--%3E%20A1%5B%22%E6%9F%A5%20VSB%20%E6%88%90%E5%BD%A2%E5%AD%94%E4%B8%8E%E5%81%8F%E8%BD%AC%E6%A0%A1%E5%87%86%22%5D%0A%20%20E2%20--%3E%20A2%5B%22%E6%9F%A5%E5%A4%9A%E6%9D%9F%E9%80%9A%E9%81%93%E7%94%B5%E6%B5%81%E4%B8%8E%E6%8B%BC%E6%8E%A5%22%5D%0A%20%20A2%20--%3E%20W%5B%22%E4%B8%8D%E8%A6%81%E5%BD%93%E6%88%90%E9%9A%8F%E6%9C%BA%E8%AF%AF%E5%B7%AE%E4%B8%A2%E7%BB%99%20OPC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"单束电流受库仑效应与亮度限制，VSB 靠加大每炮面积换时间，所以偏好大矩形。多束把总电流摊到空间独立的许多束，库仑按单束计，总剂量速率按束数加，所以偏好「把整场当成位图」。这与晶圆 EUV 光源「提高总功率」不是同一句话：这里并行的是曝光通道。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"库仑效应可以想成高峰期地铁：一节车厢塞太多人（电流大），彼此挤来挤去谁都走不直；多束像加开很多节松散车厢，每节人少、各自走得直——总运力上去了，拥挤反而变小。")],-1)),a[6]||(a[6]=E("p",null,"PEC 补偿的都是电子在抗蚀剂与衬底里的散射，但剂量背景场的时间结构不同。曲线密度场更平滑，多束 PEC 可能更稳；VSB 在密碎矩形上的雾化与加热更尖锐。电子束邻近修正不是光学 OPC，两套模型不要合并流程。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"NuFlare 与 IMS 是公开讨论里最常被对照的两条产品线，不是唯一供应商。写产能时用「VSB 家族 / 多束家族」，不要把商标写成物理定律。")],-1)),(B(),i(A,null,{default:e(()=>[s(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20GEO%5B%22%E6%8E%A9%E6%A8%A1%E5%87%A0%E4%BD%95%22%5D%20--%3E%20VSB%5B%22VSB%3A%20%E6%97%B6%E9%97%B4%E9%9A%8F%E7%82%AE%E6%95%B0%22%5D%0A%20%20GEO%20--%3E%20MB%5B%22%E5%A4%9A%E6%9D%9F%3A%20%E6%97%B6%E9%97%B4%E9%9A%8F%E9%9D%A2%E7%A7%AF%E5%89%82%E9%87%8F%22%5D%0A%20%20VSB%20--%3E%20MIX%5B%22%E6%8E%A9%E6%A8%A1%E5%8E%82%E6%B7%B7%E7%BA%BF%22%5D%0A%20%20MB%20--%3E%20MIX%0A%20%20MIX%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E5%85%89%E5%88%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多束不消除空白片缺陷与吸收体粗糙度；VSB 也不因「更老」就更准。选择标准是该层的复杂度分布、CD 规格、以及机台队列，不是节点名称。数据带宽在多束上会变成假产率：机台等数据时，面积模型算出来的小时数无效。修补、检测必须与写入器一致，曲线层尤其如此。同一层中途从 VSB 改多束，CD 基准与 PEC 都要重资格认证，不能当「换一台更快的打印机」。</p><p>后课默认：复杂 ILT 默认活在多束的面积墙上；VSB 仍是简单层与混线的支柱。</p><p>下一课的 GPU 加速若没有对应的多束队列，只是更早把炮数墙或面积墙暴露出来。</p><p><span class="marginnote">规划先进节点掩模产能，要把 ILT 层比例、多束机数量和 VSB 队列放在同一张表。只扩 GPU、不扩多束，曲线堵在掩模厂门口。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VSB 按矩形炮计数，复杂 OPC/曲线会撞炮数墙。</li><li>多束按面积与剂量计数，对复杂度一阶解耦，撞的是面积、带宽与阵列指纹。</li><li>掩模厂混线；数据准备与 PEC 必须按家族分开。</li><li>简单层 VSB 可以更优，ILT 层需要多束。</li><li>出处：IMS 多束与 NuFlare VSB 的公开写入原理。</li></ul>',7))])}const b=o(d,[["render",S]]);export{P as __pageData,b as default};
